const dadosOriginais = $('2. CAMPO DO LINK').first().json;
const respostaRede = items[0].json;
let mlbNumero = "";

// Garante a captura do texto bruto de onde quer que ele venha (body ou data)
let textoBruto = "";
if (respostaRede) {
    if (typeof respostaRede === 'string') {
        textoBruto = respostaRede;
    } else if (respostaRede.body) {
        textoBruto = typeof respostaRede.body === 'string' ? respostaRede.body : JSON.stringify(respostaRede.body);
    } else if (respostaRede.data) {
        textoBruto = typeof respostaRede.data === 'string' ? respostaRede.data : JSON.stringify(respostaRede.data);
    }
}

if (textoBruto) {
    // 🎯 O ALGORITMO EXATO DE DIVISÃO TEXTUAL DO WARLEN:
    // Divide o textão usando a palavra 'item_id' como separador estratégico
    const blocos = textoBruto.split('item_id');

    // O primeiro bloco (índice 0) é tudo o que veio antes do primeiro 'item_id'. Ignoramos.
    // Começamos a ler a partir do índice 1, que é o que vem logo após cada escrita 'item_id'
    for (let i = 1; i < blocos.length; i++) {
        let trechoAtual = blocos[i];

        // Verifica se a palavra MLB existe dentro deste trecho específico
        let posMlb = trechoAtual.indexOf('MLB');

        if (posMlb !== -1) {
            // Encontrou o MLB que veio após este item_id! 
            // Agora vamos caminhar para a frente capturando apenas os dígitos numéricos colados nele
            let idxNum = posMlb + 3;
            let acumuladorStr = "";

            while (idxNum < trechoAtual.length) {
                let char = trechoAtual.charAt(idxNum);
                if (char >= '0' && char <= '9') {
                    acumuladorStr += char;
                } else {
                    // Encontrou aspas ("), dois pontos (:), barra ou qualquer símbolo? PARA NA HORA!
                    break;
                }
                idxNum++;
            }

            // Valida se coletou um número de produto legítimo (Meli costuma ter entre 8 e 11 dígitos)
            if (acumuladorStr.length >= 7) {
                mlbNumero = acumuladorStr;
                break; // Encontrou o produto fiel do anúncio, encerra a varredura na mesma hora!
            }
        }
    }
}

// Sem mascarar! Se não encontrar nada, avisa na string para sabermos no Flutter
if (!mlbNumero || mlbNumero === "") {
    mlbNumero = "ERRO_VARREDURA_LINEAR";
}

const urlMontada = 'https://produto.mercadolivre.com.br/MLB-' + mlbNumero;
return [{ json: { url_correta: urlMontada, cookie: dadosOriginais.cookie } }];

const oldCookieString = $('5. NOVO CAMPO DO LINK').first().json.cookie || "";
const setCookieArray = $("6. Validando Sessão").first().json.headers['set-cookie'] || [];

let cookieMap = {};

if (oldCookieString) {
    oldCookieString.split(';').forEach(c => {
        const [key, ...val] = c.trim().split('=');
        if (key) cookieMap[key] = val.join('=');
    });
}

if (Array.isArray(setCookieArray)) {
    setCookieArray.forEach(c => {
        const cookiePart = c.split(';')[0];
        const [key, ...val] = cookiePart.trim().split('=');
        if (key) cookieMap[key] = val.join('=');
    });
}

const newCookieString = Object.keys(cookieMap)
    .map(key => `${key}=${cookieMap[key]}`)
    .join('; ');

return [{ json: { cookies_atualizados: newCookieString, url_final: $('5. NOVO CAMPO DO LINK').first().json.url } }];

